import re
import uuid

from app.core.config import settings
from app.core.crypto import decrypt_document, encrypt_document

_KEY_PATTERN = re.compile(r"[0-9a-f]{32}")


def _path(storage_key: str):
    # Keys are generated by us; refuse anything else so no path can escape the folder.
    if not _KEY_PATTERN.fullmatch(storage_key):
        raise ValueError("invalid storage key")
    return settings.storage_dir / f"{storage_key}.bin"


def save_encrypted(plaintext: bytes, document_id: str) -> tuple[str, bytes]:
    """Encrypt and store a file. Returns (storage_key, wrapped_key)."""
    storage_key = uuid.uuid4().hex
    encrypted, wrapped_key = encrypt_document(plaintext, document_id.encode())
    settings.storage_dir.mkdir(parents=True, exist_ok=True)
    path = _path(storage_key)
    tmp = path.with_suffix(".tmp")
    tmp.write_bytes(encrypted)
    tmp.replace(path)  # atomic: a half-written file never appears under the real name
    return storage_key, wrapped_key


def read_decrypted(storage_key: str, wrapped_key: bytes, document_id: str) -> bytes:
    encrypted = _path(storage_key).read_bytes()
    return decrypt_document(encrypted, wrapped_key, document_id.encode())


def delete_file(storage_key: str) -> None:
    _path(storage_key).unlink(missing_ok=True)